node -e "
const data = require('./app/data/data.json');
const es = {};
const en = {};

// Función para aplanar objetos anidados
function flatten(obj, prefix = '', result = {}) {
  for (const key in obj) {
    if (typeof obj[key] === 'object' && obj[key] !== null) {
      flatten(obj[key], prefix + key + '.', result);
    } else {
      result[prefix + key] = obj[key];
    }
  }
  return result;
}

// Procesar cada idioma
es['common'] = flatten(data.es);
en['common'] = flatten(data.en);

// Guardar archivos
require('fs').writeFileSync('./public/locales/es/translation.json', JSON.stringify(es, null, 2));
require('fs').writeFileSync('./public/locales/en/translation.json', JSON.stringify(en, null, 2));
console.log('Archivos de traducción creados');
"
